/**
 * 🔴 19B S1 (v4 §5, D1) — THE CLASS TABLE: every field the API serves or accepts through the contract, by its class.
 *
 * Default deny: `standard` is a class a field is GIVEN, never a default — a field with no row is unclassified, and
 * `tests/field-class-table.test.ts` fails while the contract has one (both directions: every contract field has a row,
 * every row names a field the contract has). In the test lane the seam also fails any response that serves a key
 * this table cannot classify (lib/fieldClasses/seam.ts) — the contract is not trusted to list everything served.
 *
 * Nodes are the contract's (lib/fieldClasses/shapes.ts): a component's name; an inline object's parent and property
 * (`BankingExceptions.lines.items`); an operation's inline root `<operationId>#<status>`. Each class lists its fields,
 * space-separated. A node with a protected field names the `resource` whose field grants decide it
 * (`field.<class>.<level>` in PERMISSION_MATRIX, packages/db/src/permissions.ts).
 *
 *  - `writeAlsoNeeds`: a field whose WRITE needs more classes than its own (D1: an employee's status and dates are read
 *    by everyone and written only with `compensation`; nationality also needs `compensation`, since it sets the GOSI
 *    regime; D2: a bookkeeper writes the national ID only, so the GOSI number needs `compensation`).
 *  - `conditions`: a class that applies only under a stated condition — written here, implemented by the S2 step that
 *    switches that class on (named in each condition). Until then the class applies to every row.
 *  - `by_entity`: an audit snapshot, each key classified by the audited entity's own node (the audit reader, S2c).
 *
 * Generated ONCE (2026-11-22) with a proposed class per field: v4 §5.2's inventory field by field; every other field
 * whose name matches a personal-data pattern read one by one and decided; the rest confirmed `standard`. The review —
 * every non-standard field, and every pattern match decided standard with its reason — is for the owner's approval
 * (evidence 2026-11-17-phase19-research/s1/review.md). From here on it is maintained BY HAND: a new field gets its
 * class in the commit that adds it, or the tests above fail.
 *
 * 🔴 S1 changes nothing anyone sees: every role holds every class's grants (PERMISSION_MATRIX), so nothing is withheld
 * and no write is refused. Each S2 step switches its own records on by REMOVING grants, which the reconcile applies
 * per environment only with the owner's approval of the exact set (D10).
 */
import { PROTECTED_FIELD_CLASSES, type ProtectedFieldClass } from "@workspace/db";
import { BANK_TEXT_ORIGINS } from "./conditions";

/** 19B S2c: a held change's IBAN is a PARTY's (a supplier's or an employee's) only for these kinds; the company's own
 * bank account (`bank_account_iban`, `default_bank_account`) is the business's record — standard. */
export const PARTY_IBAN_KINDS: readonly string[] = ["vendor_iban", "employee_iban"];

/**
 * 🔴 19B S2c (v4 §5.2, D9 (c)) — THE AUDIT READER. An audit entry's before/after snapshot is classified KEY BY KEY by the
 * audited entity's own node (AUDIT_ENTITY_NODES); a key that node does not list — a column the contract never serves, an
 * entity with no node — is withheld from every role but the admin. "Only the admin" is the audit trail's own grant,
 * `field.member_security.read` on `audit_logs`, which S2c leaves with the admin alone (AUDIT_UNLISTED).
 */
export const AUDIT_ENTITY_NODES: Readonly<Record<string, string>> = {
  customer: "Customer", vendor: "Vendor", employee: "Employee", invoice: "Invoice", bill: "Bill", transaction: "Transaction",
  journal_entry: "JournalEntry", payroll_run: "PayrollRun", quotation: "Quotation", purchase_order: "PurchaseOrder",
  bank_detail_change_request: "BankDetailChange",
  // bank accounts and products are served OUTSIDE the contract (no node): their snapshot keys stay the admin's only
};
export const AUDIT_UNLISTED: { cls: ProtectedFieldClass; resource: string } = { cls: "member_security", resource: "audit_logs" };

export const FIELD_CLASSES = ["standard", ...PROTECTED_FIELD_CLASSES, "by_entity"] as const;
export type FieldClass = (typeof FIELD_CLASSES)[number];

export interface NodeClasses {
  /** The matrix resource whose field grants decide this node's protected fields. Required when any field is protected. */
  resource?: string;
  standard?: string;
  contact?: string;
  identity?: string;
  compensation?: string;
  bank_account?: string;
  bank_narrative?: string;
  member_security?: string;
  by_entity?: string;
  writeAlsoNeeds?: Record<string, readonly ProtectedFieldClass[]>;
  conditions?: Record<string, string>;
  /**
   * 🔴 19B S3: the RESOURCE whose grants decide this node's protected fields, chosen PER ROW by one of the row's own
   * fields — `{ by: "kind", resources: { employee_iban: "employees" } }`: a row whose `kind` is `employee_iban` is decided
   * by the `employees` grants; any other row by `resource`. The walk applies it (walk.ts), so one served list can hold a
   * supplier's IBAN (vendors) and an employee's (employees), each withheld by its own record's grants.
   */
  rowResource?: { by: string; resources: Record<string, string> };
  /**
   * 🔴 19B S4: a protected class that applies to SOME ROWS ONLY, decided by one of the row's own fields — per field:
   * `{ description: { by: "sourceType", in: [...] } }`: `description` is its class only on a row whose `sourceType` is
   * listed (or ABSENT from the row — a row that does not say is treated as one it applies to, the safe error); on any
   * other row it is standard. The walk applies it (walk.ts) and the report datasets read it (lib/reports/datasets.ts):
   * one definition.
   */
  rowConditions?: Record<string, RowCondition>;
}

/** 19B S4: the class applies on rows whose `by` field is one of `in`, or does not say. */
export interface RowCondition { by: string; in: readonly string[] }
export const rowConditionApplies = (c: RowCondition, row: Record<string, unknown> | undefined): boolean =>
  !row || !(c.by in row) || row[c.by] == null || c.in.includes(String(row[c.by]));

export interface FieldSpec {
  cls: FieldClass;
  resource: string | null;
  writeAlsoNeeds: readonly ProtectedFieldClass[];
  /** 19B S3: the per-row resource rule of the field's node (NodeClasses.rowResource), when it has one. */
  rowResource?: { by: string; resources: Record<string, string> };
  /** 19B S4: the field's per-row condition (NodeClasses.rowConditions), when it has one. */
  rowCondition?: RowCondition;
}

